for pid, path in codebook_paths.items():
    df = pd.read_csv(path)
    entries = []
    for _, row in df.iterrows():
        keywords = '' if pd.isna(row['keywords_examples']) else str(row['keywords_examples'])
        tokens = [t.strip() for t in keywords.split(',') if t.strip()]
        weights = [token_weight(t) for t in tokens]
        entries.append(Entry(row['code'], row['standard_label'], row['station_scope'], tokens, weights))
    cb_entries[pid] = entries


