    raw_text_norm = normalize_raw(raw_text)
    raw_lower = raw_text_norm.lower()
    raw_upper = raw_text_norm.upper()
    raw_tokens = set(re.findall(r'[A-Z0-9_]+', raw_upper))
    return raw_text_norm, raw_lower, raw_tokens


def score_entry(entry: Entry, raw_text_norm: str, raw_lower: str, raw_tokens: set, station: str):
    total_w = sum(entry.weights) if entry.weights else 0
    match_w = 0
    matched_tokens = []
    for tok, w in zip(entry.tokens, entry.weights):
        if re.fullmatch(r'[A-Za-z0-9_]+', tok):
            if tok.upper() in raw_tokens:
                match_w += w
                matched_tokens.append(tok)
        else:
            if tok in raw_text_norm or tok.lower() in raw_lower:
                match_w += w
                matched_tokens.append(tok)
