    entries = cb_entries[r['product_id']]
    best = None
    best_score = -1e9
    best_tokens = []
    best_station_match = False
    second_score = -1e9

    for e in entries:
        sc, m_tokens, st_match = score_entry(e, raw_text_norm, raw_lower, raw_tokens, station)
        if sc > best_score:
            second_score = best_score
            best_score = sc
            best = e
            best_tokens = m_tokens
            best_station_match = st_match
        elif sc > second_score:
            second_score = sc

    margin = best_score - second_score if second_score > -1e8 else best_score
    unknown = best_score < THRESHOLD

    if unknown:
        pred_code = 'UNKNOWN'
        pred_label = ''
    else:
        pred_code = best.code
        pred_label = best.label

    confidence = calc_confidence(best_score, margin, best_station_match, unknown)

    rationale_parts = []
    if best_tokens:
        rationale_parts.append('keyword match: ' + ', '.join(best_tokens[:4]))
    else:
        rationale_parts.append('no keyword match')
    if station:
        rationale_parts.append('station scope match' if best_station_match else 'station scope mismatch')
    if unknown:
        rationale_parts.append(f'score below threshold ({best_score:.1f} < {THRESHOLD:.0f})')
    else:
        rationale_parts.append(f'score={best_score:.1f}')

    record_out = {
        'record_id': r['record_id'],
        'product_id': r['product_id'],
        'station': r['station'] if not pd.isna(r['station']) else '',
        'engineer_id': r['engineer_id'] if not pd.isna(r['engineer_id']) else '',
        'raw_reason_text': raw_text,
        'normalized': [
            {
                'segment_id': f"{r['record_id']}-S1",
                'span_text': raw_text,
                'pred_code': pred_code,
                'pred_label': pred_label,
                'confidence': confidence,
                'rationale': '; '.join(rationale_parts)
            }
        ]
    }
    records_out.append(record_out)

out = {'records': records_out}

with open('/app/output/solution.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)

unknowns = sum(1 for rec in records_out if rec['normalized'][0]['pred_code']=='UNKNOWN')
print('wrote', len(records_out), 'unknowns', unknowns)
